// This code has been fully generated by an AI.

package insight

import (
	"fmt"
	"math"
	"strings"
)

// TrendMetric is one value over the last 90 days compared with the 90 days
// before and the same 90 days one year earlier. Missing values are NaN.
type TrendMetric struct {
	Label   string // e.g. "Ruhepuls (Median)"
	Current float64
	// Previous are the 90 days before, LastYear the same span a year ago.
	Previous, LastYear float64
	// Threshold is the smallest change worth a statement: absolute, or a
	// fraction if Relative.
	Threshold float64
	Relative  bool
	// LowerBetter marks metrics where a decrease is an improvement
	// (resting HR, times over a distance).
	LowerBetter bool
	// Time formats values as durations and phrases changes as
	// "schneller/langsamer".
	Time bool
	// Format renders a value with its unit; Unit is appended to absolute
	// changes.
	Format func(float64) string
	Unit   string
}

// Trend is the assessment of one metric.
type Trend struct {
	Label     string
	Value     string
	Statement Statement
	Stable    bool // no change above the threshold
}

// AssessTrend compares a metric; ok is false without a current value or
// without any reference.
func AssessTrend(m TrendMetric) (Trend, bool) {
	if math.IsNaN(m.Current) || (math.IsNaN(m.Previous) && math.IsNaN(m.LastYear)) {
		return Trend{}, false
	}
	t := Trend{Label: m.Label, Value: m.Format(m.Current)}
	var parts []string
	good, bad := 0, 0
	for _, ref := range []struct {
		v    float64
		text string
	}{{m.Previous, "als die 90 Tage davor"}, {m.LastYear, "als vor einem Jahr"}} {
		if math.IsNaN(ref.v) || ref.v == 0 {
			continue
		}
		diff := m.Current - ref.v
		size := math.Abs(diff)
		amount := strings.TrimSpace(fmt.Sprintf("%s %s", trimZero(size), m.Unit))
		if m.Relative {
			size = math.Abs(diff / ref.v)
			amount = fmt.Sprintf("%.0f %%", 100*size)
		}
		if size < m.Threshold {
			continue
		}
		up := diff > 0
		word := "höher"
		switch {
		case m.Time && up:
			word = "langsamer"
		case m.Time:
			word = "schneller"
		case !up:
			word = "niedriger"
		}
		parts = append(parts, fmt.Sprintf("%s %s %s", amount, word, ref.text))
		if up != m.LowerBetter {
			good++
		} else {
			bad++
		}
	}
	if len(parts) == 0 {
		t.Stable = true
		return t, true
	}
	tone := ToneNeutral
	switch {
	case good > 0 && bad == 0:
		tone = ToneGood
	case bad > 0 && good == 0:
		tone = ToneBad
	}
	t.Statement = Statement{fmt.Sprintf("%s %s: %s", m.Label, t.Value, strings.Join(parts, ", ")), tone}
	return t, true
}

func trimZero(v float64) string {
	if v == math.Trunc(v) || v >= 10 {
		return fmt.Sprintf("%.0f", v)
	}
	return comma("%.1f", v)
}

// StableLabels lists the labels of stable trends, e.g. "Ruhepuls, HRV".
func StableLabels(ts []Trend) string {
	var l []string
	for _, t := range ts {
		if t.Stable {
			l = append(l, t.Label)
		}
	}
	return strings.Join(l, ", ")
}
